// Generated from matplotlib colormaps (plus the NWS / radar ones) — do not edit by hand.
// Each colormap is 256 RGB triplets (768 bytes), stored base64-encoded: a quarter of the size of
// the number-list form and much cheaper for the browser to parse.

function b64(s: string): Uint8Array {
  const bin = atob(s);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

