/** Register a custom colormap at runtime. */
export function registerColormap(name: string, rgb: Uint8Array): void {
  COLORMAP_DATA[name] = rgb;
}

/** Unregister a custom colormap. */
export function unregisterColormap(name: string): void {
  delete COLORMAP_DATA[name];
}

